    "id": "pm-spearwtf-3c1fd1",
    "slug": "spearwtf-3c1fd1",
    "title": "Chain.wtf pitch video",
    "category": "Motion Ads",
    "categorySlug": "motion-ads",
    "subcategory": "Kinetic Type",
